for (const item of items) {
  const d = item.json;

  const sessionId = d.sessionId || `${d.clientName || 'client'}-${d.sessionDate || new Date().toISOString().split('T')[0]}-${Date.now()}`;

  let programsSection = '';
  if (Array.isArray(d.programs) && d.programs.length > 0) {
    d.programs.forEach((p, i) => {
      const skill = p.skill || 'N/A';
      const prog = p.program || 'N/A';
      const indep = p.independence ?? 'N/A';
      const trials = p.totalTrials ?? 0;
      const prompt = p.promptType || 'no prompts required';
      programsSection += `o Program ${i + 1}: ${skill} - ${prog} Data: (${indep}% independence across ${trials} trials) (${prompt})\n`;
    });
  } else {
    programsSection = 'o No skill acquisition programs were targeted during this session.\n';
  }

  let behaviorsSection = '';
  if (Array.isArray(d.targetBehaviors) && d.targetBehaviors.length > 0) {
    d.targetBehaviors.forEach((b, i) => {
      const outcome = b.outcome ? `${b.outcome} - ${b.outcomeDescription || ''}` : 'No occurrences observed.';
      behaviorsSection += `\u2022 Target Behavior ${i + 1}: ${b.behavior || 'N/A'}\n`;
      behaviorsSection += `  o Data: ${b.instances ?? 0}\n`;
      behaviorsSection += `  o Antecedent: ${b.antecedent || 'N/A'}\n`;
      behaviorsSection += `  o Intervention Used (Reactive): ${b.interventionUsed || 'N/A'}\n`;
      behaviorsSection += `  o Outcome: ${outcome}\n`;
    });
  } else {
    behaviorsSection = '\u2022 No target behaviors were observed during this session.\n';
  }

  const parentComm = d.parentCommunicationProvided
    ? 'Yes'
    : `No${d.parentCommunicationReason ? ' - ' + d.parentCommunicationReason : ''}`;
  const transRating = d.transitionsRating || 'moderate';
  const transLabel = transRating.charAt(0).toUpperCase() + transRating.slice(1);
  const esc = (s) => (s || '').replace(/"/g, '\\"');

  const prefilledNote = `Location: ${d.location || 'Not specified'}
Session Time: ${d.sessionTime || 'Not specified'}
Participants in the session: ${d.participants || 'client, therapist'}

Session Overview
Client was present for the full duration of the session. Services were provided on a 1:1 basis.

Transitions: (${transLabel}): ${d.transitionsDescription || 'Not specified'}
Environment changes (if any): ${d.environmentChanges || 'None'}

Some of the Programs & Skill Acquisition

${programsSection}
Some of the Behavior Reduction Strategies
${behaviorsSection}
Parent/Caregiver Communication
\u2022 Was communication provided? ${parentComm}

Plan for Next Session
\u2022 Continue current programs
\u2022 Focus areas: ${d.focusAreas || 'Continue current programs'}`;

  let parentReasonJson = 'null';
  if (!d.parentCommunicationProvided && d.parentCommunicationReason) {
    parentReasonJson = '"' + esc(d.parentCommunicationReason) + '"';
  }

  const prompt = `You are a BACB-certified clinical supervisor assistant. Below is a rough draft of an ABA session note. Polish it into a professional, BACB-compliant clinical note.

=== DRAFT SESSION NOTE ===
${prefilledNote}

=== INSTRUCTIONS ===
- Improve language to be objective, professional, and clinically precise.
- Correct any grammatical or formatting issues.
- Ensure all sections follow the template structure exactly.
- Add BACB Ethics Code references relevant to the session data.
- If a section says "Not specified" or shows no data, rewrite concisely.
- Do NOT invent data that was not provided.
- Return ONLY raw JSON, no markdown, no code fences, no explanations.

=== OUTPUT FORMAT ===
{
  "id": "<UUID v4>",
  "session_date": "${esc(d.sessionDate)}",
  "client_name": "${esc(d.clientName)}",
  "rbt_name": "${esc(d.rbtName)}",
  "location": "${esc(d.location)}",
  "session_time": "${esc(d.sessionTime)}",
  "participants": "${esc(d.participants)}",
  "transitions_rating": "${transRating.toLowerCase()}",
  "transitions_description": "<polished description>",
  "environment_changes": "<polished>",
  "rendered_note": "<FULL POLISHED NOTE as plain text following template structure>",
  "programs": ${json.dumps([{'number': i+1, 'skill': p.get('skill','N/A'), 'program': p.get('program','N/A'), 'independence': str(p.get('independence','N/A'))+'%', 'trials': p.get('totalTrials',0), 'prompt_type': p.get('promptType','none')} for i, p in enumerate(d.get('programs',[]))]) if d.get('programs') else '[{"number": 1, "skill": "N/A", "program": "N/A", "independence": "0%", "trials": 0, "prompt_type": "none"}]'},
  "target_behaviors": ${json.dumps([{'number': i+1, 'behavior': b.get('behavior','N/A'), 'data': b.get('instances',0), 'antecedent': b.get('antecedent','N/A'), 'intervention': b.get('interventionUsed','N/A'), 'outcome': b.get('outcome','Positive'), 'outcome_description': b.get('outcomeDescription','')} for i, b in enumerate(d.get('targetBehaviors',[]))]) if d.get('targetBehaviors') else '[{"number": 1, "behavior": "N/A", "data": 0, "antecedent": "N/A", "intervention": "N/A", "outcome": "Positive", "outcome_description": ""}]'},
  "parent_communication_provided": ${json.dumps(bool(d.get('parentCommunicationProvided', False)))},
  "parent_communication_reason": ${parentReasonJson},
  "plan_continue_current": true,
  "plan_focus_areas": "${esc(d.focusAreas)}",
  "bacb_references": [
    {"code": "<BACB code>", "title": "<code title>", "application": "<how applied in this session>"}
  ],
  "recommendations": ["<rec 1>", "<rec 2>"],
  "created_at": "<ISO 8601 timestamp>"
}

Rules:
- rendered_note must contain the COMPLETE polished note as plain text.
- Include at least 3 BACB code references with specific applications.
- Response must be raw JSON only.`;

  item.json.chatInput = prompt;
  item.json.sessionId = sessionId;
}
return items;

for (const item of items) {
  const content = item.json.output;
  if (typeof content === 'string') {
    const cleanContent = content
      .replace(/^```(?:json)?\s*/m, '')
      .replace(/\s*```$/m, '')
      .trim();
    try {
      const parsed = JSON.parse(cleanContent);

      // Stringify object/array fields for Supabase text storage
      for (const key of ['programs', 'target_behaviors', 'bacb_references', 'recommendations']) {
        if (parsed[key] && typeof parsed[key] === 'object') {
          parsed[key] = JSON.stringify(parsed[key]);
        }
      }

      // Build structured_data as JSON string of all structured fields
      const structured = {
        location: parsed.location,
        session_time: parsed.session_time,
        participants: parsed.participants,
        transitions_rating: parsed.transitions_rating,
        transitions_description: parsed.transitions_description,
        environment_changes: parsed.environment_changes,
        programs: parsed.programs ? JSON.parse(parsed.programs) : [],
        target_behaviors: parsed.target_behaviors ? JSON.parse(parsed.target_behaviors) : [],
        parent_communication_provided: parsed.parent_communication_provided,
        parent_communication_reason: parsed.parent_communication_reason,
        plan_continue_current: parsed.plan_continue_current,
        plan_focus_areas: parsed.plan_focus_areas,
        recommendations: parsed.recommendations ? JSON.parse(parsed.recommendations) : []
      };
      parsed.structured_data = JSON.stringify(structured);

      item.json = parsed;
    } catch(e) {
      item.json = {
        error: "Failed to parse session note JSON: " + e.message,
        raw_output: content.substring(0, 500)
      };
    }
  }
}
return items;

